import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, x = data[0], data[1]

    frequencies = [1]
    for value in data[2:]:
        if value < x:
            frequencies.append(1)
        else:
            frequencies[-1] += 1

    count = len(frequencies) - 1
    square_sum = sum(value * value for value in frequencies)
    answer = [(square_sum - n - 1) // 2]

    if count:
        if all(value == frequencies[0] for value in frequencies):
            factor = frequencies[0] ** 2
            answer.extend(factor * remaining for remaining in range(count, 0, -1))
        else:
            width = (square_sum.bit_length() + 7) // 8
            packed = b"".join(
                value.to_bytes(width, "little") for value in frequencies
            )
            reversed_packed = b"".join(
                value.to_bytes(width, "little") for value in reversed(frequencies)
            )

            product = int.from_bytes(packed, "little") * int.from_bytes(
                reversed_packed, "little"
            )
            coefficients = product.to_bytes(width * (2 * count + 1), "little")

            answer.extend(
                int.from_bytes(coefficients[offset:offset + width], "little")
                for offset in range(
                    width * (count + 1), width * (2 * count + 1), width
                )
            )

    answer.extend([0] * (n - count))
    sys.stdout.write(" ".join(map(str, answer)) + "\n")


if __name__ == "__main__":
    main()
